INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein OEM immer der Hersteller des Endprodukts?', 2, '[{"text": "Nein", "correct": true, "because": "OEMs stellen oft nur Komponenten her"}, {"text": "Ja", "correct": false, "because": "Endprodukte kommen von VARs"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal eines OEM in der IT-Branche?', 3, '[{"text": "Lieferung von Komponenten", "correct": true, "because": "Für andere Marken produziert"}, {"text": "Direktverkauf an Endkunden", "correct": false, "because": "Das machen VARs"}, {"text": "Softwareentwicklung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen übernimmt ein OEM typischerweise?', 5, '[{"text": "Herstellung von Hardware", "correct": true, "because": "Liefert Bauteile wie CPUs"}, {"text": "Bereitstellung von Lizenzen", "correct": true, "because": "Z. B. Windows-OEM"}, {"text": "Endkunden-Support", "correct": false, "because": "Liegt bei VARs"}, {"text": "Marketingkampagnen", "correct": false, "because": "Nicht OEM-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OEMs verkaufen oft an Unternehmen. b) OEMs bieten immer Retail-Produkte an.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "OEMs sind B2B-fokussiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen OEM für eine Komponente wähle?', 4, '[{"text": "Qualitätssicherung", "correct": false, "because": "Entscheidend für Zuverlässigkeit"}, {"text": "Kompatibilität", "correct": false, "because": "Muss mit System passen"}, {"text": "Endkundenpreis", "correct": true, "because": "VARs setzen den Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob OEM-Software immer mit Support kommt?', 2, '[{"text": "Nein", "correct": true, "because": "Oft ohne Extras wie Support"}, {"text": "Ja", "correct": false, "because": "Support ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein OEM dasselbe wie ein ODM?', 3, '[{"text": "Nein", "correct": true, "because": "ODM entwirft, OEM produziert"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Rollen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Nutzung eines OEM?', 5, '[{"text": "Kostensenkung", "correct": true, "because": "Skaleneffekte nutzen"}, {"text": "Spezialisierung", "correct": true, "because": "Fokus auf Komponenten"}, {"text": "Direkter Retail", "correct": false, "because": "Nicht OEM-Aufgabe"}, {"text": "Produktdesign", "correct": false, "because": "Eher ODM-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass OEM-Produkte immer günstiger sind. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Dank Massenproduktion oft billiger"}, {"text": "Nein", "correct": false, "because": "Preisvorteil ist typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich mit einem OEM zusammenarbeite?', 4, '[{"text": "Zuverlässige Lieferung", "correct": true, "because": "Verhindert Produktionsstopps"}, {"text": "Kundenmarketing", "correct": false, "because": "Liegt bei VARs"}, {"text": "Softwareoptimierung", "correct": false, "because": "Sekundär für OEMs"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OEMs liefern oft ohne Verpackung. b) OEMs entwickeln immer eigene Designs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist ODM-spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature finde ich bei einem OEM entscheidend?', 4, '[{"text": "Qualitätskontrolle", "correct": true, "because": "Sichert Komponentenstandards"}, {"text": "Markenimage", "correct": false, "because": "VAR-Aufgabe"}, {"text": "Endnutzer-Support", "correct": false, "because": "Nicht OEM-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass OEM-Lizenzen an Hardware gebunden sind. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Z. B. Windows an Mainboard"}, {"text": "Nein", "correct": false, "because": "Bindung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht von einem OEM?', 3, '[{"text": "Kompatible Teile", "correct": false, "because": "Kern der Lieferung"}, {"text": "Skaleneffekte", "correct": false, "because": "Wichtig für Kosten"}, {"text": "Retail-Verpackung", "correct": true, "because": "Für VARs relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verkauft ein OEM direkt an Endkunden?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf B2B-Verkäufe"}, {"text": "Ja", "correct": false, "because": "Das machen Reseller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten könnte ein OEM liefern?', 4, '[{"text": "Prozessoren", "correct": true, "because": "Typische OEM-Produkte"}, {"text": "Festplatten", "correct": true, "because": "Häufige Komponenten"}, {"text": "Gehäusedesign", "correct": false, "because": "Eher ODM-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass OEM-Teile immer besser als Aftermarket sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität ist kontextabhängig"}, {"text": "Ja", "correct": false, "because": "Aftermarket kann überlegen sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines OEM?', 3, '[{"text": "Produktionskapazität", "correct": true, "because": "Sichert Lieferfähigkeit"}, {"text": "Kundenbewertungen", "correct": false, "because": "Sekundär für B2B"}, {"text": "Social Media", "correct": false, "because": "Irrelevant für OEMs"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OEMs sparen Kosten durch Skalierung. b) OEMs bieten immer Garantie.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Garantie liegt bei VARs"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein OEM auch Software liefern kann?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Betriebssystem-Lizenzen"}, {"text": "Nein", "correct": false, "because": "Software ist üblich"}]');
